"""
Collect pCloudy App Performance Observability API responses.

Uses the token generated by the existing GitHub Actions pCloudy authentication
step. No second authentication request is made here.
"""
import json
import os
import urllib.error
import urllib.request
from datetime import datetime, timezone
from pathlib import Path

OBSERVABILITY_ENDPOINTS = {
    "session-details": "/api/observability/sessions/details",
    "session-issues": "/api/observability/sessions/issues",
    "network-analysis": "/api/observability/network/analysis",
    "ui-jank-analysis": "/api/observability/uiinsights/jank/analysis",
    "key-observations": "/api/observability/sessions/key-observations",
    "jank-frame-analysis": "/api/observability/uiinsights/jank/frame-analysis",
    "network-apdex": "/api/observability/network/apdex",
}
DEFAULT_OBS_URL = "https://observability-backend.pcloudy.com"
DEFAULT_ORIGIN = "https://observability-device.pcloudy.com"


def _write_json(path, data):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(data, indent=2, ensure_ascii=False, default=str) + "\n",
        encoding="utf-8",
    )


def _post(url, token, origin, session_id):
    body = json.dumps({"sessionId": session_id}).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=body,
        method="POST",
        headers={
            "token": token,
            "Origin": origin,
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=90) as response:
            status = response.status
            raw = response.read().decode("utf-8", errors="replace")
    except urllib.error.HTTPError as exc:
        status = exc.code
        raw = exc.read().decode("utf-8", errors="replace")
    except Exception as exc:
        return {
            "success": False,
            "http_status": None,
            "response": None,
            "error": f"{type(exc).__name__}: {exc}",
        }

    try:
        parsed = json.loads(raw) if raw else None
    except json.JSONDecodeError:
        parsed = {"raw_response": raw}

    ok = 200 <= status < 300
    return {
        "success": ok,
        "http_status": status,
        "response": parsed,
        "error": None if ok else "HTTP request failed",
    }


def collect_observability(session_id, output_dir, token=None, origin=None):
    token = token or os.getenv("PCLOUDY_TOKEN", "")
    origin = origin or os.getenv("PCLOUDY_ORIGIN", DEFAULT_ORIGIN)
    base_url = os.getenv("PCLOUDY_OBS_URL", DEFAULT_OBS_URL).rstrip("/")
    out = Path(output_dir)
    out.mkdir(parents=True, exist_ok=True)

    summary = {
        "sessionId": session_id,
        "collectedAt": datetime.now(timezone.utc).isoformat(),
        "observabilityBaseUrl": base_url,
        "results": {},
    }

    if not token:
        summary.update({
            "status": "FAILED",
            "error": "PCLOUDY_TOKEN is empty; pass the token from the existing auth step.",
            "successCount": 0,
            "failureCount": len(OBSERVABILITY_ENDPOINTS),
        })
        _write_json(out / "observability-summary.json", summary)
        return {"status": "FAILED", "success_count": 0, "failure_count": 7}

    successes = 0
    failures = 0
    for name, endpoint in OBSERVABILITY_ENDPOINTS.items():
        result = _post(
            f"{base_url}{endpoint}", token, origin, session_id
        )
        summary["results"][name] = {"endpoint": endpoint, **result}
        _write_json(out / f"{name}.json", result)
        if result["success"]:
            successes += 1
            print(f"[OBSERVABILITY] {name}: HTTP {result['http_status']}")
        else:
            failures += 1
            print(f"[OBSERVABILITY] {name}: request failed")

    status = "SUCCESS" if failures == 0 else ("PARTIAL" if successes else "FAILED")
    summary.update({
        "status": status,
        "successCount": successes,
        "failureCount": failures,
    })
    _write_json(out / "observability-summary.json", summary)
    return {
        "status": status,
        "success_count": successes,
        "failure_count": failures,
    }
